WITH root AS(SELECT r.revision_sha256,r.canonical_preimage::jsonb tuple FROM mission_factory_owner.editor_release_readiness r WHERE singleton),
wanted(signature) AS (VALUES ('public.clan_innata_staff_profile_state_v1(uuid,uuid)'),('public.clan_innata_staff_profile_set_v1(uuid,uuid,text,uuid,bigint)'),('clan_innata_narrative_private.staff_profile_for_character_v1(uuid,uuid,uuid)'),('clan_innata_narrative_private.command_admitted_v1(uuid,uuid,uuid)'),('clan_innata_narrative_private.activate_v1(uuid,uuid,uuid,uuid,uuid)'),('clan_innata_narrative_private.quote_v1(uuid,boolean)'),('clan_innata_private.sharingan_combat_scope_core(uuid,boolean)'),('clan_innata_private.sharingan_staff_bind_ready(uuid)'),('clan_innata_private.combat_scope(uuid,uuid)'),('clan_innata_private.combat_activation_window(uuid,uuid)'),('clan_innata_private.combat_begin_turn(uuid,uuid)'),('clan_innata_private.combat_terminal(uuid,uuid,text)'),('clan_innata_private.combat_transition(uuid,uuid,text,uuid,bigint)'),('clan_innata_private.sharingan_consumer_options(jsonb)'),('clan_innata_private.sharingan_master_control_offers(uuid,bigint)'),('clan_innata_private.sharingan_commit_control(jsonb,jsonb)'),('clan_innata_private.sharingan_commit_master_control(jsonb)'),('clan_innata_private.sharingan_off_offer_valid(uuid,uuid)'),('clan_hyuga_private.sedici_common_cost_guard()'),('clan_innata_narrative_private.byakugan_family_guard_v1()'),('clan_innata_narrative_private.staff_profile_actor_v1(uuid)'),('clan_innata_narrative_private.staff_profile_bind_v1(uuid,uuid)'),('public.post_message(uuid,text,uuid,uuid,text)'),('clan_innata_narrative_private.materialize_v1(uuid)'),('clan_aburame_private.staff_scope(uuid)'),('clan_aburame_private.actor_allowed(uuid)'),('clan_aburame_private.actor_has_technique(uuid,uuid)'),('clan_aburame_private.ensure_scope(uuid)'),('clan_inuzuka_private.owner_scope(uuid,boolean)'),('clan_inuzuka_private.staff_profile_needed(uuid)'),('clan_inuzuka_private.staff_profile_apply(uuid)'),('clan_marionettisti_private.consumer_options(jsonb)'),('clan_marionettisti_private.staff_profile_bind(uuid,jsonb)'),('public.combat_test_restore_resources_v1(uuid,uuid)')),
new_wanted(signature) AS (VALUES ('clan_innata_narrative_private.catalog_v2()'),('clan_innata_narrative_private.profile_definition_v2(text)'),('clan_innata_narrative_private.profile_definition_by_id_v2(uuid)'),('clan_innata_narrative_private.permission_fact_v2(uuid)'),('clan_innata_narrative_private.profile_busy_reason_v2(uuid)'),('clan_innata_narrative_private.profile_state_core_v2(uuid,uuid)'),('public.clan_innata_staff_profile_state_v2(uuid,uuid)'),('public.clan_innata_staff_profile_set_v2(uuid,uuid,text,uuid,bigint)'),('clan_innata_narrative_private.sharingan_selected_v2(uuid)'),('clan_innata_narrative_private.sharingan_quote_for_actor_v2(uuid)'),('clan_innata_narrative_private.permission_role_link_v2(uuid,uuid,uuid)')),
targets AS (SELECT f.* FROM wanted w CROSS JOIN LATERAL (SELECT w.signature,p.oid,n.nspname,p.proname,p.proowner::regrole::text owner,p.proacl::text acl,p.proconfig config,p.prosecdef secdef,l.lanname language,p.provolatile::text volatility,p.proisstrict strict,p.proparallel::text parallel,p.proleakproof leakproof,p.prokind::text kind,p.proargnames arg_names,p.proargmodes arg_modes,p.proargtypes::text arg_types,pg_get_function_result(p.oid)returns,md5(p.prosrc)source_md5,md5(pg_get_functiondef(p.oid))ddl_md5 FROM(SELECT w.signature::text signature)w LEFT JOIN pg_proc p ON p.oid=to_regprocedure(w.signature)LEFT JOIN pg_namespace n ON n.oid=p.pronamespace LEFT JOIN pg_language l ON l.oid=p.prolang) f),
relation_names(name) AS (
 SELECT jsonb_object_keys(tuple#>'{db_core,combat_innata_relations}') FROM root
 UNION SELECT unnest(ARRAY['clan_innata_private.config_versions','clan_innata_private.editorial_approvals','clan_innata_narrative_private.config_quotes_v1','clan_innata_narrative_private.contexts_v1','clan_hyuga_private.staff_profiles','public.messages']::text[])
 UNION SELECT n.nspname||'.'||c.relname FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE t.tgfoid IN(SELECT to_regprocedure(signature)::oid FROM wanted) AND NOT t.tgisinternal
),
relations AS (SELECT r.* FROM relation_names rn CROSS JOIN LATERAL (SELECT w.name,c.oid,c.relkind::text kind,c.relowner::regrole::text owner,c.relacl::text acl,c.relrowsecurity rls,c.relforcerowsecurity force_rls,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attnum),'[]'::jsonb)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)columns,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.conname,'ddl',pg_get_constraintdef(x.oid),'validated',x.convalidated)ORDER BY x.conname),'[]'::jsonb)FROM pg_constraint x WHERE x.conrelid=c.oid)constraints,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled::text,'ddl',pg_get_triggerdef(t.oid),'function_md5',md5(pg_get_functiondef(t.tgfoid)))ORDER BY t.tgname),'[]'::jsonb)FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)triggers,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.polname,'command',x.polcmd::text,'permissive',x.polpermissive,'roles',to_jsonb(x.polroles),'using',pg_get_expr(x.polqual,x.polrelid),'with_check',pg_get_expr(x.polwithcheck,x.polrelid))ORDER BY x.polname),'[]'::jsonb)FROM pg_policy x WHERE x.polrelid=c.oid)policies,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',x.indexrelid::regclass::text,'ddl',pg_get_indexdef(x.indexrelid))ORDER BY x.indexrelid::regclass::text),'[]'::jsonb)FROM pg_index x WHERE x.indrelid=c.oid)indexes,
 CASE WHEN c.relkind='v'THEN pg_get_viewdef(c.oid,true)END view FROM(SELECT rn.name::text name)w LEFT JOIN pg_class c ON c.oid=to_regclass(w.name)) r),
dep_wanted(signature) AS (
 SELECT n.nspname||'.'||p.proname||'('||replace(oidvectortypes(p.proargtypes),', ', ',')||')' FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE (n.nspname='clan_innata_narrative_private' AND p.proname IN('ensure_context_v1','staff_profile_active_ids_v1','scope_v1'))
 OR (n.nspname='clan_innata_private' AND p.proname IN('state_set_core','combat_context'))
 OR (n.nspname='combat_consumer_private' AND p.proname IN('staff_test_allowed','staff_test_policy'))
),
dependencies AS (SELECT f.* FROM dep_wanted w CROSS JOIN LATERAL(SELECT w.signature,p.oid,n.nspname,p.proname,p.proowner::regrole::text owner,p.proacl::text acl,p.proconfig config,p.prosecdef secdef,l.lanname language,p.provolatile::text volatility,p.proisstrict strict,p.proparallel::text parallel,p.proleakproof leakproof,p.prokind::text kind,p.proargnames arg_names,p.proargmodes arg_modes,p.proargtypes::text arg_types,pg_get_function_result(p.oid)returns,md5(p.prosrc)source_md5,md5(pg_get_functiondef(p.oid))ddl_md5 FROM(SELECT w.signature::text signature)w LEFT JOIN pg_proc p ON p.oid=to_regprocedure(w.signature)LEFT JOIN pg_namespace n ON n.oid=p.pronamespace LEFT JOIN pg_language l ON l.oid=p.prolang)f)
SELECT jsonb_build_object('schema_version','innata-all-root-target-actual/1','captured_at',clock_timestamp(),'root_revision',(SELECT revision_sha256 FROM root),
 'targets',(SELECT jsonb_agg(to_jsonb(f) ORDER BY signature) FROM targets f),
 'new_functions',(SELECT jsonb_agg(jsonb_build_object('signature',signature,'oid',to_regprocedure(signature)::oid) ORDER BY signature) FROM new_wanted),
 'relations',(SELECT jsonb_agg(to_jsonb(r) ORDER BY name) FROM relations r),
 'dependencies',(SELECT jsonb_agg(to_jsonb(f) ORDER BY signature) FROM dependencies f),
 'config_tables',jsonb_build_object('clan_innata_private.config_versions',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text),'[]'::jsonb) FROM clan_innata_private.config_versions q),'clan_innata_private.editorial_approvals',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text),'[]'::jsonb) FROM clan_innata_private.editorial_approvals q),'clan_innata_narrative_private.config_quotes_v1',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text),'[]'::jsonb) FROM clan_innata_narrative_private.config_quotes_v1 q)),
 'catalog',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.clan_techniques t WHERE t.id=ANY(ARRAY['94c45ec9-78c7-423e-9045-4b4cf2104b15','d2d98dad-fb9f-4ff1-b6b2-3d3f2d222fae','6d264e00-1db3-4daa-b7cc-e5f011e1dab1','2fb3e027-a4ff-4058-9d5d-0212facb3f68','bc2569b5-eab4-44b4-9843-c199724caff4','09097efd-e162-4cae-a644-5e643fe94f8c','dd2026b4-bffc-490e-8646-be411d4746b3','fdf79ce1-1c5b-44c4-aaa1-789be08e01de','ed808bc6-57f6-4853-80bf-9e6985ca0cc3','41254b82-5b5e-46e9-9820-b3d604bbe38f','2fb9e210-225d-460a-a9f9-39ee64f8fce1','ab64415a-cca3-472f-9203-84ad60c09405','4a527ff2-0420-4da9-bc1f-5489c753b285','8e20bafe-cb3c-4967-b9c7-2a4bca694996','9b384de3-35f0-43c0-b145-94f985fa758a','a50808fa-e7cd-45ee-b4d4-33ad8c65d472','b0748ef4-bea8-4d85-95a1-7d9db1b4381c','843031ac-521a-4c5b-832e-37a0398a9862','537945fc-b7a3-4661-8144-e3fbcd6b24d0','d48b7246-44bf-4ecc-a4dc-a9bb705c331a','4d742b75-2592-4379-81c0-07ddf436f32b','6e4b8efc-e324-404a-a8c7-b4c39b8070b8','559606f3-f3a0-401d-9e8c-7685624bb880','7fef3cc6-ec43-49a2-a740-cd9f4ee1c31a','20341270-6241-45cd-9633-437d3ce80447','32d0749c-6167-45da-8880-bb3f60dd401f','a4704025-1ef8-43c9-9e5b-113582a7e621','6c56bb2f-4936-4c43-873e-dde65fe42d2b','001f907c-8f32-4758-8a16-ad1730e72c59','e6cc70fa-7ef3-4eaf-afb7-4ca6f588c2b4','efd15ad1-c1ae-4495-aaa5-0f9415f4be0a','e0456437-21d5-4a04-9d8a-9bffbf87c26d','4056f62d-77f3-47f9-8ecb-9a7799682a9d','65b30dec-6f9f-459e-b78c-49173d74f251','f3673da7-42c9-497e-abe1-1c0982429f35','1ab6d359-f337-45ed-839c-4e626d2e2819']::uuid[])),
 'native_gates',jsonb_build_object('eyes',(SELECT to_jsonb(g) FROM clan_hyuga_private.release_gate g WHERE singleton),'sabaku',(SELECT to_jsonb(g) FROM clan_sabaku_private.release_gate g WHERE singleton),'aburame',(SELECT to_jsonb(g) FROM clan_aburame_private.release_gate g WHERE singleton),'inuzuka',(SELECT to_jsonb(g) FROM clan_inuzuka_private.release_gate g WHERE singleton),'marionettisti',(SELECT to_jsonb(g) FROM clan_marionettisti_private.release_gate g WHERE singleton))
) capture;
